/**
 * Replace vague autogenerated "Run the reference check" copy in the reader
 * with specific, source-grounded directions. The source workbook and the
 * original commands/expected results stay untouched for traceability.
 * Keys are lesson ID plus the one-based step number.
 */
export const clarifiedChecks: Record<string, { title: string; action: string }> = {
  'lab-09:7': {
    title: 'Confirm each forest can find the other forest’s domain controllers',
    action: 'After configuring the conditional forwarders, open Windows PowerShell on the authorized lab servers. Run each nslookup using the DNS-server IP shown in the command. The -type=SRV lookup asks that DNS server for LDAP domain-controller service records in the opposite forest. Compare both returned records to the expected forest; do not mistake a successful DNS lookup for proof that an AD trust exists.',
  },
  'lab-10:10': {
    title: 'Verify the destination GPO exists in the correct domain',
    action: 'On DEST-DC01 open Windows PowerShell with the appropriate domain permissions. Run Get-GPO using the destination GPO name and -Domain migrate.lab.example.test, then open Group Policy Management to confirm the linked OU and banner setting. A GPO existing without a link does not mean it applies to clients.',
  },
  'lab-11:10': {
    title: 'Verify APP01 joined the destination domain and still serves IIS',
    action: 'On APP01 after the planned reboot, open PowerShell. Run each line in order: identify the machine and domain, inspect the W3SVC IIS service, probe destination DNS on TCP 53, request a GPO refresh, and use gpresult to inspect effective computer policy. Open the website separately to verify the application actually responds; a running service by itself is insufficient.',
  },
  'lab-12:7': {
    title: 'Validate the rolled-back computer identity, DNS, policy, and web service',
    action: 'On the APP01 practice server, use PowerShell to read the current domain membership and full network/DNS settings, then inspect effective computer policy and the IIS service. Compare the output with the rollback target recorded before your test. Do not call the recovery successful until both the domain trust and application work are confirmed.',
  },
  'sql-04:6': {
    title: 'Create a disposable Helpdesk database and two sample tickets',
    action: 'Open SSMS connected to the intended SQL01 instance, select New Query, and read the complete script. CREATE DATABASE makes AgencyHelpdesk, USE sets the query context, CREATE TABLE defines ticket columns, INSERT creates two fake tickets, and SELECT displays them. GO separates batches in SSMS; do not paste these SQL statements into PowerShell.',
  },
  'sql-04:7': {
    title: 'Read the two tickets back without modifying the database',
    action: 'In SSMS on SQL01, open a new query window connected to the correct instance. USE AgencyHelpdesk selects your practice database. SELECT the TicketID, Summary, and Status columns from dbo.Tickets to confirm both inserted rows are present. SELECT is a read operation; this query does not migrate or back up the database.',
  },
  'mecm-01:7': {
    title: 'Prove MECM01 has a domain identity and can reach SQL01',
    action: 'On MECM01 run PowerShell. Check the hostname and joined Windows domain, resolve SQL01.lab.example.test to an address, and probe SQL Server TCP port 1433. Compare the result to the lab’s documented server name and address; a successful TCP port check does not prove SQL permissions.',
  },
  'mecm-02:9': {
    title: 'Check MECM01 network access and its SQL login separately',
    action: 'On MECM01 run only the Test-NetConnection PowerShell command to check SQL01 port 1433. The following line is a comment reminding you to open SSMS on SQL01 and inspect Security > Logins for the LAB\\MECM01$ computer identity. The network check and SQL permission check are separate; confirm both rather than assuming open TCP means authorized SQL access.',
  },
  'mecm-04:8': {
    title: 'Confirm SQL and the managed client service are healthy',
    action: 'On SQL01 use an authorized PowerShell session to check Get-Service MSSQLSERVER. Separately, on APP01, if the ConfigMgr client was installed, check Get-Service CcmExec. Then verify client status in the MECM console after the SQL dependency is available. The two service queries must run on their own named servers.',
  },
  'move-02:11': {
    title: 'Compare SQL source and restored target ticket counts',
    action: 'Use SSMS to connect to SQL01 and then separately to the target Azure SQL VM. Run the provided read-only database status and ticket-count queries on each instance. Compare counts and database state, then perform the documented application and login checks. A matching row count is useful evidence but does not alone prove migration success.',
  },
  'lab-15:11': {
    title: 'Prove Azure DC DNS and AD work over the private network',
    action: 'Inside AZ-DC01, use an authorized elevated Windows PowerShell session to inspect Get-ADDomain, ipconfig /all, and the SRV lookup against the stated private DNS address. Confirm the intended domain and private interface. Also inspect Azure NIC/NSG settings to verify AD/RDP services are not directly exposed to the internet.',
  },
  'lab-16:8': {
    title: 'Test private cloud DNS resolution and TCP connectivity',
    action: 'From the designated on-prem lab test machine, replace the placeholder agency DNS and Azure private IP addresses with your own verified values. Query the cloud domain-controller SRV record, then test the private destination on TCP port 53. If private connectivity has not been established, do not force a cutover: document the planned deferral.',
  },
};

export function checkTeachingFor(lessonId: string, stepNumber: number) {
  return clarifiedChecks[lessonId + ':' + stepNumber];
}
